import java.util.Arrays;

class Solution {
    public int findContentChildren(int[] g, int[] s) {
        g = g.clone();
        s = s.clone();
        Arrays.sort(g);
        Arrays.sort(s);
        int child = 0;
        for (int cookie = 0; cookie < s.length && child < g.length; cookie++) {
            if (s[cookie] >= g[child]) {
                child++; // 当前饼干满足最小的待满足胃口
            }
        }
        return child;
    }
}

