class Solution {
    public int maxSubArray(int[] nums) {
        int sum = 0;
        int result = nums[0];
        for (int num : nums) {
            sum += num;
            result = Math.max(result, sum);
            if (sum < 0) sum = 0; // 负前缀不带到下一段
        }
        return result;
    }
}

